def post(samples, result):
    # A press is registered at index i when readings i-2, i-1, i are all 1
    # and this is the first such moment in its run of 1s. That means either
    # i == 2 (the run starts at index 0) or the reading at i-3 is 0.
    # Each maximal run of 1s with length >= 3 therefore gives exactly one press.
    n = len(samples)
    count = 0
    for i in range(2, n):
        if samples[i] == 1 and samples[i - 1] == 1 and samples[i - 2] == 1:
            if i == 2:
                count += 1
            elif samples[i - 3] == 0:
                count += 1
    return result == count
